using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using BookStudio.Application.Authoring;
using Microsoft.Data.Sqlite;

namespace BookStudio.Infrastructure.Persistence.Sqlite.Research;

public sealed class SqliteCitationBibliographyStore : ICitationBibliographyStore, IAsyncDisposable
{
    private readonly SqliteConnectionFactory _factory;
    private readonly SqliteWriteQueue _queue;
    private int _disposed;

    public SqliteCitationBibliographyStore(SqliteConnectionFactory factory, int capacity = 64)
    {
        _factory = factory ?? throw new ArgumentNullException(nameof(factory));
        _queue = new SqliteWriteQueue(factory, capacity);
    }

    public ValueTask<CitationBibliographyCreateResult> CreateAsync(CitationBibliographyDraft d, DateTimeOffset at, CancellationToken ct = default)
    {
        ValidateDraft(d);
        var hash = Hash(JsonSerializer.Serialize(d));
        return _queue.ExecuteInTransactionAsync((c, tx, token) =>
        {
            token.ThrowIfCancellationRequested();
            var existing = Read(c, tx, d.WorkspaceId, d.BibliographyId);
            if (existing is not null)
            {
                var receipt = ReadReceipt(c, tx, d.WorkspaceId, d.BibliographyId) ?? throw new CitationBibliographyConflictException("Create receipt missing.");
                RequireReceipt(receipt, "CREATE", d.WorkspaceId, d.BibliographyId, d.RequestFingerprint, hash);
                return new CitationBibliographyCreateResult(existing, true);
            }
            RequireAuthority(c, tx, d.WorkspaceId, d.ProjectId, d.ClaimVerificationId, d.ExpectedClaimVerificationRevision, d.ExpectedClaimVerificationDigest);
            var message = MessageId(d.BibliographyId);
            Execute(c, tx, "INSERT INTO citation_bibliographies(workspace_id,bibliography_id,project_id,claim_verification_id,expected_claim_verification_revision,expected_claim_verification_digest,version,citation_style,locale,actor,snapshot_json,revision,status,decision,decision_reason,message_id,created_at_utc,updated_at_utc) VALUES($w,$id,$p,$verification,$r,$digest,$v,$style,$locale,$actor,$snapshot,1,'PROPOSED',NULL,NULL,$m,$at,$at);", ("$w", d.WorkspaceId), ("$id", d.BibliographyId.ToString("D")), ("$p", d.ProjectId.ToString("D")), ("$verification", d.ClaimVerificationId.ToString("D")), ("$r", d.ExpectedClaimVerificationRevision), ("$digest", d.ExpectedClaimVerificationDigest), ("$v", d.Version), ("$style", d.CitationStyle), ("$locale", d.Locale), ("$actor", d.Actor), ("$snapshot", d.SnapshotJson), ("$m", message.ToString("D")), ("$at", Text(at)));
            InsertHistory(c, tx, d.WorkspaceId, d.BibliographyId, 1, "CREATE", d.Actor, null, new { d.ClaimVerificationId, d.CitationStyle, d.Locale }, at);
            InsertReceipt(c, tx, d.WorkspaceId, d.BibliographyId, d.BibliographyId, "CREATE", d.RequestFingerprint, hash, 1, message, at);
            InsertOutbox(c, tx, message, "citation.bibliography.proposed", new { d.WorkspaceId, d.BibliographyId, d.ProjectId, d.Actor }, at);
            return new CitationBibliographyCreateResult(Require(c, tx, d.WorkspaceId, d.BibliographyId), false);
        }, ct);
    }

    public ValueTask<CitationBibliography> ValidateAsync(CitationBibliographyValidateCommand cmd, DateTimeOffset at, CancellationToken ct = default)
    {
        ValidateContent(cmd.Citations, cmd.Entries);
        if (string.IsNullOrWhiteSpace(cmd.Evidence)) throw new CitationBibliographyValidationException("Validation evidence is required.");
        return Mutate(cmd.RequestId, cmd.WorkspaceId, cmd.BibliographyId, "VALIDATE", cmd.RequestFingerprint, Hash(JsonSerializer.Serialize(cmd)), cmd.ExpectedRevision, at, (c, tx, item) =>
        {
            if (!AuthorityMatches(c, tx, item)) return MarkStaleCore(c, tx, item, cmd.RequestId, "Claim verification authority drift.", cmd.Actor, at);
            if (item.Status is CitationBibliographyStatus.Approved or CitationBibliographyStatus.Rejected or CitationBibliographyStatus.Stale) throw new CitationBibliographyTransitionException("Bibliography cannot be validated from its current state.");
            ReplaceContent(c, tx, item.WorkspaceId, item.BibliographyId, cmd.Citations, cmd.Entries);
            return Advance(c, tx, item, CitationBibliographyStatus.Validated, cmd.RequestId, "VALIDATE", cmd.Actor, cmd.Evidence, new { CitationCount = cmd.Citations.Count, EntryCount = cmd.Entries.Count }, "citation.bibliography.validated", at);
        }, ct);
    }

    public ValueTask<CitationBibliography> DecideAsync(CitationBibliographyDecisionCommand cmd, DateTimeOffset at, CancellationToken ct = default)
    {
        if (string.IsNullOrWhiteSpace(cmd.Reason)) throw new CitationBibliographyValidationException("Decision reason is required.");
        return Mutate(cmd.RequestId, cmd.WorkspaceId, cmd.BibliographyId, "DECIDE", cmd.RequestFingerprint, Hash(JsonSerializer.Serialize(cmd)), cmd.ExpectedRevision, at, (c, tx, item) =>
        {
            if (!AuthorityMatches(c, tx, item)) return MarkStaleCore(c, tx, item, cmd.RequestId, "Claim verification authority drift.", cmd.Actor, at);
            if (item.Status != CitationBibliographyStatus.Validated) throw new CitationBibliographyTransitionException("Only validated bibliographies can be decided.");
            if (item.Citations.Count == 0 || item.Entries.Count == 0) throw new CitationBibliographyTransitionException("Citations and bibliography entries are required.");
            if (cmd.Decision == CitationBibliographyDecision.Approve)
            {
                if (item.Citations.Any(x => !x.MetadataValid || !x.LinkValid || !x.IsCurrent || string.IsNullOrWhiteSpace(x.Evidence))) throw new CitationBibliographyTransitionException("Invalid, stale or unsupported citation prevents approval.");
                if (item.Entries.Any(x => !x.MetadataValid || !x.IsCurrent || string.IsNullOrWhiteSpace(x.Evidence))) throw new CitationBibliographyTransitionException("Invalid, stale or unsupported bibliography entry prevents approval.");
                if (item.Entries.Select(x => x.CanonicalKey).Distinct(StringComparer.OrdinalIgnoreCase).Count() != item.Entries.Count) throw new CitationBibliographyTransitionException("Duplicate canonical bibliography entries prevent approval.");
                var sourceIds = item.Entries.Select(x => x.SourceId).ToHashSet();
                if (item.Citations.Any(x => !sourceIds.Contains(x.SourceId))) throw new CitationBibliographyTransitionException("Every citation must resolve to a bibliography source.");
            }
            var status = cmd.Decision switch { CitationBibliographyDecision.Approve => CitationBibliographyStatus.Approved, CitationBibliographyDecision.Reject => CitationBibliographyStatus.Rejected, _ => CitationBibliographyStatus.RepairRequired };
            return Advance(c, tx, item, status, cmd.RequestId, "DECIDE", cmd.Actor, cmd.Reason, new { cmd.Decision }, $"citation.bibliography.{status.ToString().ToLowerInvariant()}", at, decision: cmd.Decision);
        }, ct);
    }

    public ValueTask<CitationBibliography> ReopenAsync(CitationBibliographyReopenCommand cmd, DateTimeOffset at, CancellationToken ct = default) => Mutate(cmd.RequestId, cmd.WorkspaceId, cmd.BibliographyId, "REOPEN", cmd.RequestFingerprint, Hash(JsonSerializer.Serialize(cmd)), cmd.ExpectedRevision, at, (c, tx, item) =>
    {
        if (string.IsNullOrWhiteSpace(cmd.Reason)) throw new CitationBibliographyValidationException("Reopen reason is required.");
        if (item.Status is CitationBibliographyStatus.Proposed or CitationBibliographyStatus.Validated or CitationBibliographyStatus.Stale) throw new CitationBibliographyTransitionException("Bibliography cannot be reopened from its current state.");
        return Advance(c, tx, item, CitationBibliographyStatus.Proposed, cmd.RequestId, "REOPEN", cmd.Actor, cmd.Reason, new { cmd.Reason }, "citation.bibliography.reopened", at, clearContent: true);
    }, ct);

    public ValueTask<CitationBibliography> MarkStaleAsync(CitationBibliographyStaleCommand cmd, DateTimeOffset at, CancellationToken ct = default) => Mutate(cmd.RequestId, cmd.WorkspaceId, cmd.BibliographyId, "STALE", cmd.RequestFingerprint, Hash(JsonSerializer.Serialize(cmd)), cmd.ExpectedRevision, at, (c, tx, item) => MarkStaleCore(c, tx, item, cmd.RequestId, cmd.Reason, cmd.Actor, at), ct);
    public async ValueTask<CitationBibliography?> GetAsync(string workspaceId, Guid bibliographyId, CancellationToken ct = default) { ct.ThrowIfCancellationRequested(); using var c = _factory.OpenConnection(); return await Task.FromResult(Read(c, null, workspaceId, bibliographyId)); }
    public async ValueTask DisposeAsync() { if (Interlocked.Exchange(ref _disposed, 1) == 0) await _queue.DisposeAsync().ConfigureAwait(false); }

    private ValueTask<CitationBibliography> Mutate(Guid requestId, string workspace, Guid id, string action, string fingerprint, string hash, long expectedRevision, DateTimeOffset at, Func<SqliteConnection, SqliteTransaction, CitationBibliography, CitationBibliography> mutation, CancellationToken ct) => _queue.ExecuteInTransactionAsync((c, tx, token) => { token.ThrowIfCancellationRequested(); var receipt = ReadReceipt(c, tx, workspace, requestId); if (receipt is not null) { RequireReceipt(receipt, action, workspace, id, fingerprint, hash); return Require(c, tx, workspace, id); } var item = Require(c, tx, workspace, id); if (item.Revision != expectedRevision) throw new CitationBibliographyConflictException("Stale revision."); var result = mutation(c, tx, item); InsertReceipt(c, tx, workspace, requestId, id, action, fingerprint, hash, result.Revision, result.MessageId, at); return result; }, ct);
    private static CitationBibliography Advance(SqliteConnection c, SqliteTransaction tx, CitationBibliography item, CitationBibliographyStatus status, Guid request, string action, string actor, string? reason, object payload, string eventType, DateTimeOffset at, bool clearContent = false, CitationBibliographyDecision? decision = null) { var revision = item.Revision + 1; var message = MessageId(request); if (clearContent) { Execute(c, tx, "DELETE FROM citations WHERE workspace_id=$w AND bibliography_id=$id;", ("$w", item.WorkspaceId), ("$id", item.BibliographyId.ToString("D"))); Execute(c, tx, "DELETE FROM bibliography_entries WHERE workspace_id=$w AND bibliography_id=$id;", ("$w", item.WorkspaceId), ("$id", item.BibliographyId.ToString("D"))); } Execute(c, tx, "UPDATE citation_bibliographies SET revision=$r,status=$s,decision=$d,decision_reason=$reason,message_id=$m,updated_at_utc=$at WHERE workspace_id=$w AND bibliography_id=$id;", ("$r", revision), ("$s", status.ToString().ToUpperInvariant()), ("$d", decision is null ? DBNull.Value : decision.Value.ToString().ToUpperInvariant()), ("$reason", reason is null ? DBNull.Value : reason), ("$m", message.ToString("D")), ("$at", Text(at)), ("$w", item.WorkspaceId), ("$id", item.BibliographyId.ToString("D"))); InsertHistory(c, tx, item.WorkspaceId, item.BibliographyId, revision, action, actor, reason, payload, at); InsertOutbox(c, tx, message, eventType, new { item.WorkspaceId, item.BibliographyId, Actor = actor }, at); return Require(c, tx, item.WorkspaceId, item.BibliographyId); }
    private static CitationBibliography MarkStaleCore(SqliteConnection c, SqliteTransaction tx, CitationBibliography item, Guid request, string reason, string actor, DateTimeOffset at) { if (string.IsNullOrWhiteSpace(reason)) throw new CitationBibliographyValidationException("Stale reason is required."); if (item.Status is CitationBibliographyStatus.Approved or CitationBibliographyStatus.Rejected) throw new CitationBibliographyTransitionException("Final bibliography cannot be marked stale."); return Advance(c, tx, item, CitationBibliographyStatus.Stale, request, "STALE", actor, reason, new { reason }, "citation.bibliography.stale", at); }

    private static void ValidateDraft(CitationBibliographyDraft d) { if (d.BibliographyId == Guid.Empty || d.ProjectId == Guid.Empty || d.ClaimVerificationId == Guid.Empty || d.ExpectedClaimVerificationRevision < 1 || d.Version < 1 || string.IsNullOrWhiteSpace(d.WorkspaceId) || string.IsNullOrWhiteSpace(d.ExpectedClaimVerificationDigest) || string.IsNullOrWhiteSpace(d.CitationStyle) || string.IsNullOrWhiteSpace(d.Locale) || string.IsNullOrWhiteSpace(d.Actor) || string.IsNullOrWhiteSpace(d.SnapshotJson) || string.IsNullOrWhiteSpace(d.RequestFingerprint)) throw new CitationBibliographyValidationException("Complete citation bibliography draft is required."); }
    private static void ValidateContent(IReadOnlyList<CitationDraft> citations, IReadOnlyList<BibliographyEntryDraft> entries) { if (citations is null || citations.Count == 0 || entries is null || entries.Count == 0) throw new CitationBibliographyValidationException("Citations and bibliography entries are required."); if (citations.Select(x => x.CitationId).Distinct().Count() != citations.Count || entries.Select(x => x.EntryId).Distinct().Count() != entries.Count) throw new CitationBibliographyValidationException("Ids must be unique."); foreach (var x in citations) if (x.CitationId == Guid.Empty || x.ClaimId == Guid.Empty || x.SourceId == Guid.Empty || string.IsNullOrWhiteSpace(x.Location) || string.IsNullOrWhiteSpace(x.Locator) || string.IsNullOrWhiteSpace(x.RenderedText) || string.IsNullOrWhiteSpace(x.Evidence)) throw new CitationBibliographyValidationException("Complete citation data is required."); foreach (var x in entries) if (x.EntryId == Guid.Empty || x.SourceId == Guid.Empty || string.IsNullOrWhiteSpace(x.CanonicalKey) || string.IsNullOrWhiteSpace(x.Title) || string.IsNullOrWhiteSpace(x.RenderedText) || string.IsNullOrWhiteSpace(x.Evidence)) throw new CitationBibliographyValidationException("Complete bibliography metadata is required."); }
    private static void RequireAuthority(SqliteConnection c, SqliteTransaction tx, string workspace, Guid project, Guid verificationId, long expectedRevision, string expectedDigest) { using var cmd = c.CreateCommand(); cmd.Transaction = tx; cmd.CommandText = "SELECT project_id,revision,status FROM claim_verifications WHERE workspace_id=$w AND verification_id=$id;"; cmd.Parameters.AddWithValue("$w", workspace); cmd.Parameters.AddWithValue("$id", verificationId.ToString("D")); using var r = cmd.ExecuteReader(); if (!r.Read()) throw new CitationBibliographyValidationException("Verified claim authority was not found."); var storedProject = Guid.Parse(r.GetString(0)); var revision = r.GetInt64(1); var status = r.GetString(2); var digest = Hash($"{workspace}:{verificationId:D}:{revision}:{status}"); if (storedProject != project || revision != expectedRevision || status != "VERIFIED" || digest != expectedDigest) throw new CitationBibliographyValidationException("Claim verification authority is not exact and verified."); }
    private static bool AuthorityMatches(SqliteConnection c, SqliteTransaction tx, CitationBibliography item) { try { RequireAuthority(c, tx, item.WorkspaceId, item.ProjectId, item.ClaimVerificationId, item.ExpectedClaimVerificationRevision, item.ExpectedClaimVerificationDigest); return true; } catch (CitationBibliographyValidationException) { return false; } }

    private sealed record Receipt(string Workspace, Guid BibliographyId, string Action, string Fingerprint, string Hash);
    private static Receipt? ReadReceipt(SqliteConnection c, SqliteTransaction? tx, string w, Guid request) { using var cmd = c.CreateCommand(); cmd.Transaction = tx; cmd.CommandText = "SELECT workspace_id,bibliography_id,action,request_fingerprint,payload_hash FROM citation_bibliography_receipts WHERE workspace_id=$w AND request_id=$r;"; cmd.Parameters.AddWithValue("$w", w); cmd.Parameters.AddWithValue("$r", request.ToString("D")); using var x = cmd.ExecuteReader(); return x.Read() ? new(x.GetString(0), Guid.Parse(x.GetString(1)), x.GetString(2), x.GetString(3), x.GetString(4)) : null; }
    private static void RequireReceipt(Receipt r, string action, string workspace, Guid id, string fingerprint, string hash) { if (r.Workspace != workspace || r.BibliographyId != id || r.Action != action || r.Fingerprint != fingerprint || r.Hash != hash) throw new CitationBibliographyConflictException("Request id reused with different payload."); }
    private static CitationBibliography Require(SqliteConnection c, SqliteTransaction? tx, string w, Guid id) => Read(c, tx, w, id) ?? throw new CitationBibliographyValidationException("Citation bibliography not found.");
    private static CitationBibliography? Read(SqliteConnection c, SqliteTransaction? tx, string w, Guid id) { using var cmd = c.CreateCommand(); cmd.Transaction = tx; cmd.CommandText = "SELECT project_id,claim_verification_id,expected_claim_verification_revision,expected_claim_verification_digest,version,citation_style,locale,actor,snapshot_json,revision,status,decision,decision_reason,message_id,created_at_utc,updated_at_utc FROM citation_bibliographies WHERE workspace_id=$w AND bibliography_id=$id;"; cmd.Parameters.AddWithValue("$w", w); cmd.Parameters.AddWithValue("$id", id.ToString("D")); using var r = cmd.ExecuteReader(); if (!r.Read()) return null; var x = new { Project = Guid.Parse(r.GetString(0)), Verification = Guid.Parse(r.GetString(1)), VerificationRevision = r.GetInt64(2), Digest = r.GetString(3), Version = r.GetInt32(4), Style = r.GetString(5), Locale = r.GetString(6), Actor = r.GetString(7), Snapshot = r.GetString(8), Revision = r.GetInt64(9), Status = Enum.Parse<CitationBibliographyStatus>(r.GetString(10), true), Decision = r.IsDBNull(11) ? (CitationBibliographyDecision?)null : Enum.Parse<CitationBibliographyDecision>(r.GetString(11), true), Reason = r.IsDBNull(12) ? null : r.GetString(12), Message = r.IsDBNull(13) ? (Guid?)null : Guid.Parse(r.GetString(13)), Created = DateTimeOffset.Parse(r.GetString(14), CultureInfo.InvariantCulture), Updated = DateTimeOffset.Parse(r.GetString(15), CultureInfo.InvariantCulture) }; r.Close(); var citations = new List<Citation>(); using (var q = c.CreateCommand()) { q.Transaction = tx; q.CommandText = "SELECT citation_id,claim_id,source_id,kind,location,locator,rendered_text,metadata_valid,link_valid,is_current,evidence FROM citations WHERE workspace_id=$w AND bibliography_id=$id ORDER BY citation_id;"; q.Parameters.AddWithValue("$w", w); q.Parameters.AddWithValue("$id", id.ToString("D")); using var e = q.ExecuteReader(); while (e.Read()) citations.Add(new(Guid.Parse(e.GetString(0)), Guid.Parse(e.GetString(1)), Guid.Parse(e.GetString(2)), Enum.Parse<CitationKind>(e.GetString(3), true), e.GetString(4), e.GetString(5), e.GetString(6), e.GetInt32(7) != 0, e.GetInt32(8) != 0, e.GetInt32(9) != 0, e.GetString(10))); } var entries = new List<BibliographyEntry>(); using (var q = c.CreateCommand()) { q.Transaction = tx; q.CommandText = "SELECT entry_id,source_id,canonical_key,title,author,publisher,year,doi,isbn,url,rendered_text,metadata_valid,is_current,evidence FROM bibliography_entries WHERE workspace_id=$w AND bibliography_id=$id ORDER BY entry_id;"; q.Parameters.AddWithValue("$w", w); q.Parameters.AddWithValue("$id", id.ToString("D")); using var e = q.ExecuteReader(); while (e.Read()) entries.Add(new(Guid.Parse(e.GetString(0)), Guid.Parse(e.GetString(1)), e.GetString(2), e.GetString(3), e.IsDBNull(4) ? null : e.GetString(4), e.IsDBNull(5) ? null : e.GetString(5), e.IsDBNull(6) ? null : e.GetInt32(6), e.IsDBNull(7) ? null : e.GetString(7), e.IsDBNull(8) ? null : e.GetString(8), e.IsDBNull(9) ? null : e.GetString(9), e.GetString(10), e.GetInt32(11) != 0, e.GetInt32(12) != 0, e.GetString(13))); } return new(id, x.Project, w, x.Verification, x.VerificationRevision, x.Digest, x.Version, x.Style, x.Locale, x.Actor, x.Snapshot, x.Revision, x.Status, citations, entries, x.Decision, x.Reason, x.Message, x.Created, x.Updated); }
    private static void ReplaceContent(SqliteConnection c, SqliteTransaction tx, string w, Guid id, IReadOnlyList<CitationDraft> citations, IReadOnlyList<BibliographyEntryDraft> entries) { Execute(c, tx, "DELETE FROM citations WHERE workspace_id=$w AND bibliography_id=$id;", ("$w", w), ("$id", id.ToString("D"))); Execute(c, tx, "DELETE FROM bibliography_entries WHERE workspace_id=$w AND bibliography_id=$id;", ("$w", w), ("$id", id.ToString("D"))); foreach (var x in citations) Execute(c, tx, "INSERT INTO citations(workspace_id,bibliography_id,citation_id,claim_id,source_id,kind,location,locator,rendered_text,metadata_valid,link_valid,is_current,evidence) VALUES($w,$id,$cid,$claim,$source,$kind,$location,$locator,$rendered,$metadata,$link,$current,$evidence);", ("$w", w), ("$id", id.ToString("D")), ("$cid", x.CitationId.ToString("D")), ("$claim", x.ClaimId.ToString("D")), ("$source", x.SourceId.ToString("D")), ("$kind", x.Kind.ToString().ToUpperInvariant()), ("$location", x.Location), ("$locator", x.Locator), ("$rendered", x.RenderedText), ("$metadata", x.MetadataValid ? 1 : 0), ("$link", x.LinkValid ? 1 : 0), ("$current", x.IsCurrent ? 1 : 0), ("$evidence", x.Evidence)); foreach (var x in entries) Execute(c, tx, "INSERT INTO bibliography_entries(workspace_id,bibliography_id,entry_id,source_id,canonical_key,title,author,publisher,year,doi,isbn,url,rendered_text,metadata_valid,is_current,evidence) VALUES($w,$id,$eid,$source,$key,$title,$author,$publisher,$year,$doi,$isbn,$url,$rendered,$metadata,$current,$evidence);", ("$w", w), ("$id", id.ToString("D")), ("$eid", x.EntryId.ToString("D")), ("$source", x.SourceId.ToString("D")), ("$key", x.CanonicalKey), ("$title", x.Title), ("$author", x.Author is null ? DBNull.Value : x.Author), ("$publisher", x.Publisher is null ? DBNull.Value : x.Publisher), ("$year", x.Year is null ? DBNull.Value : x.Year.Value), ("$doi", x.Doi is null ? DBNull.Value : x.Doi), ("$isbn", x.Isbn is null ? DBNull.Value : x.Isbn), ("$url", x.Url is null ? DBNull.Value : x.Url), ("$rendered", x.RenderedText), ("$metadata", x.MetadataValid ? 1 : 0), ("$current", x.IsCurrent ? 1 : 0), ("$evidence", x.Evidence)); }
    private static void InsertHistory(SqliteConnection c, SqliteTransaction tx, string w, Guid id, long rev, string action, string actor, string? reason, object payload, DateTimeOffset at) => Execute(c, tx, "INSERT INTO citation_bibliography_history(workspace_id,bibliography_id,revision,action,actor,reason,payload_json,occurred_at_utc) VALUES($w,$id,$r,$a,$actor,$reason,$p,$at);", ("$w", w), ("$id", id.ToString("D")), ("$r", rev), ("$a", action), ("$actor", actor), ("$reason", reason is null ? DBNull.Value : reason), ("$p", JsonSerializer.Serialize(payload)), ("$at", Text(at)));
    private static void InsertReceipt(SqliteConnection c, SqliteTransaction tx, string w, Guid request, Guid id, string action, string fingerprint, string hash, long rev, Guid? message, DateTimeOffset at) => Execute(c, tx, "INSERT INTO citation_bibliography_receipts(workspace_id,request_id,bibliography_id,action,request_fingerprint,payload_hash,resulting_revision,message_id,created_at_utc) VALUES($w,$r,$id,$a,$f,$h,$v,$m,$at);", ("$w", w), ("$r", request.ToString("D")), ("$id", id.ToString("D")), ("$a", action), ("$f", fingerprint), ("$h", hash), ("$v", rev), ("$m", message is null ? DBNull.Value : message.Value.ToString("D")), ("$at", Text(at)));
    private static void InsertOutbox(SqliteConnection c, SqliteTransaction tx, Guid message, string type, object payload, DateTimeOffset at) => Execute(c, tx, "INSERT INTO outbox_messages(message_id,event_type,schema_version,payload_json,occurred_at_utc,available_at_utc,status,attempts,locked_by,locked_until_utc,last_error,processed_at_utc,created_at_utc) VALUES($id,$t,'1.0',$p,$at,$at,'PENDING',0,NULL,NULL,NULL,NULL,$at);", ("$id", message.ToString("D")), ("$t", type), ("$p", JsonSerializer.Serialize(payload)), ("$at", Text(at)));
    private static void Execute(SqliteConnection c, SqliteTransaction tx, string sql, params (string Name, object Value)[] values) { using var cmd = c.CreateCommand(); cmd.Transaction = tx; cmd.CommandText = sql; foreach (var (n, v) in values) cmd.Parameters.AddWithValue(n, v); cmd.ExecuteNonQuery(); }
    private static Guid MessageId(Guid request) => new(SHA256.HashData(request.ToByteArray()).AsSpan(0, 16));
    private static string Hash(string value) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))).ToLowerInvariant();
    private static string Text(DateTimeOffset value) => value.ToUniversalTime().ToString("O", CultureInfo.InvariantCulture);
}